-Buffer::Buffer(const char *fileName)
-    : max(0), memory(nullptr), size(0) {
-    // std::cout << "Buffer(char *) = "<< std::endl;
-    struct stat st;
-    stat(fileName, &st);
-    if (S_ISREG(st.st_mode)) {
-        int fd = ::open(fileName, O_RDONLY);
