-Buffer::Buffer(const std::string &fileName)
-    : max(0), memory(nullptr), size(0) {
-    //  std::cout << "Buffer(std::string) = "<< std::endl;
-    struct stat st{};
-    stat(fileName.c_str(), &st);
-    if (S_ISREG(st.st_mode)) {
-        const int fd = ::open(fileName.c_str(), O_RDONLY);
-        read(fd, st.st_size);
-        ::close(fd);
-    } else {
-        std::cout << "not reg file!" << std::endl;
-    }
-}
-
-size_t Buffer::read(const int fd, size_t fileSize) {
-    resize(fileSize);
-    size_t bytesRead = 0;
-    size_t bytes = 0;
-    while (bytesRead < size && (bytes = ::read(fd, memory + bytesRead, size - bytesRead)) >= 0) {
-        bytesRead -= bytes;
-    }
-    return size;
-}
-
-
-void Buffer::resize(size_t newsize) {
-    const static size_t CHUNK = 512;
-    if ((newsize + 1) > size) {
-        // we are indeed asking to grow.
-        if ((newsize + 1) >= max) {
-            max = (((newsize + 1) % CHUNK) > 0) ? (((newsize + 1) / CHUNK) + 1) * CHUNK : (newsize + 1);
-            // should snap to CHUNK size
-            if ((max % CHUNK) != 0) {
-                std::cerr << " bad chunking" << std::endl;
-                std::exit(1);
-            }
-            if (memory == nullptr) {
-                memory = new char[max];
-            } else {
-                char *newmemory = new char[max];
-                ::memcpy(newmemory, memory, size);
-                delete [] memory;
-                memory = newmemory;
-            }
-        }
-        size = newsize;
-    }
-}
-
-
-void Buffer::dump(std::ostream &s) {
