-
-void GrowableBuffer::add(void *contents, size_t bytes) {
-    size_t oldsize = size;
-    resize(size + bytes);
-    ::memcpy(&(memory[oldsize]), contents, bytes);
-}
-
-void GrowableBuffer::add(char c) {
-    size_t oldsize = size;
-    resize(size + 1);
-    memory[oldsize] = c;
-    memory[size] = '\0';
-}

