-#define BUF_SIZE 4096
-
-void fsutil::send(int from, size_t bytes, int to) {
-    char buf[BUF_SIZE];
-    size_t bytesRead;
-    size_t totalSent = 0;
-    size_t bytesSent;
-    while (bytes > 0
-           && (((bytesRead = read(from, buf, ((bytes < BUF_SIZE) ? bytes : BUF_SIZE)))) > 0)
-           && (((bytesSent = ::write(to, buf, bytesRead))) > 0)) {
-        bytes -= bytesRead;
-        totalSent += bytesRead;
-    }
-    if (bytesSent == 0) {
-        perror("sendfile: send() transferred 0 bytes");
-    }
-}
